50	     * otherwise 'PHONE'.
51	     */
52	    default OwnerDto.ContactPreferenceEnum toContactPreference(Owner owner) {
53	        String email = owner.getEmail();
54	        return (email != null && !email.isBlank())
55	                ? OwnerDto.ContactPreferenceEnum.EMAIL
56	                : OwnerDto.ContactPreferenceEnum.PHONE;
